	for _, want := range []string{amendContestCompartment, "120", "100"} {
		if !strings.Contains(msg, want) {
			t.Fatalf("超重说明应包含 %q（指出舱位、预计总重量 120 千克与最大承重 100 千克）: %s",
				want, msg)
		}
